def transpose_records(records):
    keys = []
    seen = set()
    for record in records:
        for key in record:
            if key not in seen:
                seen.add(key)
                keys.append(key)
    if not keys:
        return []
    return [[key, [record.get(key) for record in records]] for key in keys]
